const body = $json.body ?? $json;
const headers = $json.headers ?? {};
const errors = [];

if (!Array.isArray(body.ingredients)) {
  errors.push('ingredients muss ein Array sein.');
}
const rawIngredients = Array.isArray(body.ingredients) ? body.ingredients : [];
if (rawIngredients.length < 1 || rawIngredients.length > 20) {
  errors.push('Es sind 1 bis 20 Zutaten erlaubt.');
}

const ingredients = rawIngredients.map((item, index) => {
  const name = String(item?.name ?? '').trim();
  const amount = Number(item?.amount);
  const unit = String(item?.unit ?? 'gram').trim();
  if (!name || name.length > 60) errors.push(`Zutat ${index + 1}: ungültiger Name.`);
  if (!Number.isFinite(amount) || amount <= 0 || amount > 10000) errors.push(`Zutat ${index + 1}: ungültige Menge.`);
  if (!unit || unit.length > 20) errors.push(`Zutat ${index + 1}: ungültige Einheit.`);
  return { name, amount, unit };
});

const p = body.preferences ?? {};
const portions = Number(p.portions ?? 2);
const cookingPersons = Number(p.cookingPersons ?? 1);
const cookingTime = String(p.cookingTime ?? 'quick');
const cuisine = String(p.cuisine ?? 'German').trim();
const diet = String(p.diet ?? 'No preferences').trim();
if (!Number.isInteger(portions) || portions < 1 || portions > 12) errors.push('Portionen müssen zwischen 1 und 12 liegen.');
if (!Number.isInteger(cookingPersons) || cookingPersons < 1 || cookingPersons > 2) errors.push('Es sind 1 oder 2 kochende Personen erlaubt.');
if (!['quick', 'medium', 'complex'].includes(cookingTime)) errors.push('Ungültige Kochzeit.');
if (!cuisine || cuisine.length > 50) errors.push('Ungültige Küchenrichtung.');
if (!diet || diet.length > 50) errors.push('Ungültige Ernährungspräferenz.');

// For local development, requests without a reverse-proxy IP share one bucket.
// For public deployment, only trust X-Forwarded-For when it is set by your own trusted proxy.
const forwarded = String(headers['x-forwarded-for'] ?? headers['X-Forwarded-For'] ?? '').split(',')[0].trim();
const realIp = String(headers['x-real-ip'] ?? headers['X-Real-IP'] ?? '').trim();
const clientKey = forwarded || realIp || 'local-client';
const requestId = `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;

return [{ json: {
  valid: errors.length === 0,
  errors,
  clientKey,
  requestId,
  ingredients,
  preferences: { portions, cookingPersons, cookingTime, cuisine, diet }
}}];

const input = $input.first().json;

// Text aus der Basic LLM Chain auslesen
let raw = input.text ?? input.output ?? input.response;

if (raw === undefined || raw === null) {
  throw new Error(
    'Keine Gemini-Antwort gefunden. Prüfe den Output der Basic LLM Chain.'
  );
}

// JSON-Text oder bereits vorhandenes Objekt verarbeiten
let data;

if (typeof raw === 'string') {
  const cleaned = raw
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  try {
    data = JSON.parse(cleaned);
  } catch (error) {
    throw new Error(
      'Gemini hat kein gültiges JSON zurückgegeben: ' +
      String(error.message)
    );
  }
} else {
  data = raw;
}

// Prüfen, ob drei Rezepte vorhanden sind
if (
  !data ||
  !Array.isArray(data.recipes) ||
  data.recipes.length !== 3
) {
  throw new Error(
    'Gemini muss genau 3 Rezepte im Feld "recipes" zurückgeben.'
  );
}

// Rezeptdaten validieren und formatieren
const recipes = data.recipes.map((recipe, index) => {
  if (!recipe || !recipe.title || !Array.isArray(recipe.steps)) {
    throw new Error(
      `Rezept ${index + 1} hat keinen Titel oder keine Kochschritte.`
    );
  }

  return {
    id: index + 1,
    title: recipe.title,
    cookingTime: recipe.cookingTime ?? 'Unknown',
    cookingPersons: recipe.cookingPersons ?? 1,
    tags: Array.isArray(recipe.tags) ? recipe.tags : [],
    yourIngredients: Array.isArray(recipe.yourIngredients)
      ? recipe.yourIngredients
      : [],
    extraIngredients: Array.isArray(recipe.extraIngredients)
      ? recipe.extraIngredients
      : [],
    steps: recipe.steps.map((step, stepIndex) => ({
      number: stepIndex + 1,
      title: step.title ?? `Step ${stepIndex + 1}`,
      description: step.description ?? '',
      chef: step.chef ?? 'Chef 1'
    })),
    nutrition: {
      calories: recipe.nutrition?.calories ?? 'N/A',
      protein: recipe.nutrition?.protein ?? 'N/A',
      fat: recipe.nutrition?.fat ?? 'N/A',
      carbs: recipe.nutrition?.carbs ?? 'N/A'
    }
  };
});

return [
  {
    json: {
      recipes
    }
  }
];

const input = $input.first()?.json ?? {};
const err = input.error ?? {};
const message = String(err.message ?? input.message ?? 'Unbekannter Fehler bei der Rezeptgenerierung').slice(0, 1000);
const logEntry = {
  timestamp: new Date().toISOString(),
  workflowName: $workflow.name,
  executionId: String($execution.id ?? ''),
  failedNode: String(input.node?.name ?? input.lastNodeExecuted ?? 'Basic LLM Chain / Parse 3 Recipes'),
  errorMessage: message,
  category: 'RECIPE_GENERATION_FAILED'
};
// The sanitized log entry remains visible in this execution's data in n8n.
return [{ json: { logEntry, error: 'RECIPE_GENERATION_FAILED', message: 'Die Rezepte konnten gerade nicht erstellt werden. Bitte versuche es erneut.' } }];

const body = $json.body ?? $json;
const allowedStatus = Number(body.httpStatus);
const safe = {
  timestamp: String(body.timestamp ?? new Date().toISOString()).slice(0, 50),
  operation: String(body.operation ?? 'unknown').slice(0, 80),
  httpStatus: Number.isInteger(allowedStatus) && allowedStatus >= 100 && allowedStatus <= 599 ? allowedStatus : null,
  category: String(body.category ?? 'CLIENT_ERROR').slice(0, 80),
  requestId: String(body.requestId ?? '').slice(0, 100),
  message: String(body.message ?? '').slice(0, 300)
};
// Do not forward arbitrary payloads, ingredient lists, headers or credentials.
return [{ json: { received: true, clientErrorLog: safe } }];

const item = $input.first().json;
if (!item.valid) {
  return [{ json: {
    allowed: false,
    statusCode: 400,
    error: 'INVALID_REQUEST',
    message: 'Die Anfrage enthält ungültige Daten.',
    details: item.errors,
    requestId: item.requestId
  }}];
}

// Best-effort local-development quota. Workflow static data is not atomic and is not
// suitable as production-grade rate limiting under concurrent/public traffic.
const store = $getWorkflowStaticData('global');
if (!Array.isArray(store.recipeRequestLog)) store.recipeRequestLog = [];
const now = Date.now();
const windowMs = 10 * 60 * 1000;
store.recipeRequestLog = store.recipeRequestLog.filter(entry => now - entry.timestamp < windowMs);
const clientKey = String(item.clientKey || 'local-client');
const recent = store.recipeRequestLog.filter(entry => entry.clientKey === clientKey);
if (recent.length >= 5) {
  const oldest = recent.reduce((min, entry) => Math.min(min, entry.timestamp), Infinity);
  const retryAfterSeconds = Math.max(1, Math.ceil((oldest + windowMs - now) / 1000));
  return [{ json: {
    allowed: false,
    statusCode: 429,
    error: 'RATE_LIMIT_EXCEEDED',
    message: 'Zu viele Anfragen. Bitte versuche es später erneut.',
    retryAfterSeconds,
    requestId: item.requestId
  }}];
}
store.recipeRequestLog.push({ clientKey, timestamp: now });
return [{ json: {
  allowed: true,
  requestId: item.requestId,
  ingredients: item.ingredients,
  preferences: item.preferences
}}];
